INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c43166d7-0904-5005-87ae-2e92d2d20673', 'Sweden Act amending the Annual Accounts Act (1995:1554)', 'Act amending the Annual Accounts Act (1995:1554)', 'The Act amending the Annual Accounts Act (1995:1554) introduces new sustainability reporting requirements for certain companies in Sweden. These provisions will first apply to financial years starting after the end of 2026 for some companies, and after the end of 2027 for others. The act aims to enhance transparency in corporate sustainability practices. It is mandatory for specified companies, aligning with EU directives on sustainability reporting.', 'The Act amending the Annual Accounts Act (1995:1554) introduces new sustainability reporting requirements for certain companies in Sweden. These provisions will first apply to financial years starting after the end of 2026 for some companies, and after the end of 2027 for others. The act aims to enhance transparency in corporate sustainability practices. It is mandatory for specified companies, aligning with EU directives on sustainability reporting.', 'The Act amending the Annual Accounts Act (1995:1554) introduces new sustainability reporting requirements for certain companies in Sweden. These provisions will first apply to financial years starting after the end of 2026 for some companies, and after the end of 2027 for others. The act aims to enhance transparency in corporate sustainability practices. It is mandatory for specified companies, aligning with EU directives on sustainability reporting.', 'Sweden', 'climate', 'in_force', '2025-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_29', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3a68e1e3-ecb3-5812-8010-6c81a525a09e', 'Sweden Act amending the Act on annual accounts', 'Act amending the Act on annual accounts in credit institutions and securities companies (1995: 1559)', 'The Act amending the Act on annual accounts in credit institutions and securities companies introduces new sustainability reporting requirements for certain financial institutions in Sweden. It mandates that companies specified in the annual accounts law must apply these new sustainability reporting provisions starting from the fiscal year following the end of 2026 or 2027, depending on the type of institution. This policy applies to credit institutions and securities companies, making it a mandatory requirement for compliance with sustainability reporting standards.', 'The Act amending the Act on annual accounts in credit institutions and securities companies introduces new sustainability reporting requirements for certain financial institutions in Sweden. It mandates that companies specified in the annual accounts law must apply these new sustainability reporting provisions starting from the fiscal year following the end of 2026 or 2027, depending on the type of institution. This policy applies to credit institutions and securities companies, making it a mandatory requirement for compliance with sustainability reporting standards.', 'The Act amending the Act on annual accounts in credit institutions and securities companies introduces new sustainability reporting requirements for certain financial institutions in Sweden. It mandates that companies specified in the annual accounts law must apply these new sustainability reporting provisions starting from the fiscal year following the end of 2026 or 2027, depending on the type of institution. This policy applies to credit institutions and securities companies, making it a mandatory requirement for compliance with sustainability reporting standards.', 'Sweden', 'climate', 'in_force', '2025-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_30', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('007b44d6-204b-53e5-8348-211b42655fa5', 'Sweden Act amending the Act on annual accounts', 'Act amending the Act on annual accounts in insurance companies (1995: 1560)', 'The Act amending the Act on annual accounts in insurance companies introduces new sustainability reporting requirements for insurance companies in Sweden. These requirements will first apply to companies for the fiscal year starting after 2026, with specific provisions for different types of companies. The act aims to enhance transparency and accountability in sustainability practices within the insurance sector. It is mandatory for the specified companies to comply with these new reporting standards.', 'The Act amending the Act on annual accounts in insurance companies introduces new sustainability reporting requirements for insurance companies in Sweden. These requirements will first apply to companies for the fiscal year starting after 2026, with specific provisions for different types of companies. The act aims to enhance transparency and accountability in sustainability practices within the insurance sector. It is mandatory for the specified companies to comply with these new reporting standards.', 'The Act amending the Act on annual accounts in insurance companies introduces new sustainability reporting requirements for insurance companies in Sweden. These requirements will first apply to companies for the fiscal year starting after 2026, with specific provisions for different types of companies. The act aims to enhance transparency and accountability in sustainability practices within the insurance sector. It is mandatory for the specified companies to comply with these new reporting standards.', 'Sweden', 'climate', 'in_force', '2025-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_31', ARRAY['regulati