INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8116ad02-062c-5302-bd2a-1b98fdbbd137', 'Sweden Implementation of the Pay Transparency Directive', 'Implementation of the Pay Transparency Directive', 'Sweden''s 2024 policy focuses on implementing the Pay Transparency Directive to enforce equal pay principles. It involves amendments to discrimination laws, involves various stakeholders like employers and unions, and aims to provide insight into wage setting mechanisms for equal treatment of men and women.', 'Sweden''s 2024 policy focuses on implementing the Pay Transparency Directive to enforce equal pay principles. It involves amendments to discrimination laws, involves various stakeholders like employers and unions, and aims to provide insight into wage setting mechanisms for equal treatment of men and women.', 'Sweden''s 2024 policy focuses on implementing the Pay Transparency Directive to enforce equal pay principles. It involves amendments to discrimination laws, involves various stakeholders like employers and unions, and aims to provide insight into wage setting mechanisms for equal treatment of men and women.', 'Sweden', 'social', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_15', ARRAY['sdg10', 'regulations', 'mandatory', 'sdg5', 'sdg16', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7d01faeb-aaa2-535a-a0e6-105dd9e6c014', 'Sweden Annual Accounts Act (1995:1554)', 'Annual Accounts Act (1995:1554)', 'The Annual Accounts Act (1995:1554) in Sweden, updated in 2024, outlines changes to financial reporting laws, specifying signing requirements for various types of organizations. It focuses on ensuring accurate financial disclosures and transparency, targeting companies, partnerships, and entities within the Swedish business sector.', 'The Annual Accounts Act (1995:1554) in Sweden, updated in 2024, outlines changes to financial reporting laws, specifying signing requirements for various types of organizations. It focuses on ensuring accurate financial disclosures and transparency, targeting companies, partnerships, and entities within the Swedish business sector.', 'The Annual Accounts Act (1995:1554) in Sweden, updated in 2024, outlines changes to financial reporting laws, specifying signing requirements for various types of organizations. It focuses on ensuring accurate financial disclosures and transparency, targeting companies, partnerships, and entities within the Swedish business sector.', 'Sweden', 'climate', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_16', ARRAY['regulations', 'sdg17', 'mandatory', 'sdg16', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d254311e-d79f-582e-9049-07a3436444c4', 'Sweden Swedish Companies Act (2005:551)', 'Swedish Companies Act (2005:551)', 'The Swedish Companies Act (2005:551) amendment in 2024 focuses on changes to regulations concerning company registration, responsibilities, and penalties for non-compliance. It targets businesses operating in Sweden, emphasizing accurate record-keeping, proper representation, and legal adherence.', 'The Swedish Companies Act (2005:551) amendment in 2024 focuses on changes to regulations concerning company registration, responsibilities, and penalties for non-compliance. It targets businesses operating in Sweden, emphasizing accurate record-keeping, proper representation, and legal adherence.', 'The Swedish Companies Act (2005:551) amendment in 2024 focuses on changes to regulations concerning company registration, responsibilities, and penalties for non-compliance. It targets businesses operating in Sweden, emphasizing accurate record-keeping, proper representation, and legal adherence.', 'Sweden', 'governance', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_17', ARRAY['sweden', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('777db9e3-d312-5443-b55d-25f4417931db', 'Sweden Auditors Act (2001:883)', 'Auditors Act (2001:883)', 'The Auditors Act (2001:883) amendment in Sweden, 2024, defines roles and requirements for auditors, inspections, and registration. It aims to ensure ethical auditing practices, oversee audit activities, and establish standards for auditors, firms, and third-country auditors operating in Sweden.', 'The Auditors Act (2001:883) amendment in Sweden, 2024, defines roles and requirements for auditors, inspections, and registration. It aims to ensure ethical auditing practices, oversee audit activities, and establish standards for auditors, firms, and third-country auditors operating in Sweden.', 'The Auditors Act (2001:883) amendment in Sweden, 2024, defines roles and requirements for auditors, inspections, and registration. It aims to ensure ethical auditing practices, oversee audit activities, and establish standards for auditors, firms, and third-country auditors operating in Sweden.', 'Sweden', 'governance', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_18', ARRAY['sweden', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0d0a6a4e-97a0-50c2-99a4-342795b60efc', 'Sweden Act (2004:297) on Banking and Financing Activities', 'Act (2004:297) on Banking and Financing Activities', 'The 2024 Swedish Act amending the Banking and Financing Activities Act outlines obligations for credit institutions to disclose individual information for criminal investigations. Investigative authorities can impose disclosure restrictions to prevent compromising investigations, with time limits and international cooperation considerations.', 'The 2024 Swedish Act amending the Banking and Financing Activities Act outlines obligations for credit institutions to disclose individual information for criminal investigations. Investigative authorities can impose disclosure restrictions to prevent compromising investigations, with time limits and international cooperation considerations.', 'The 2024 Swedish Act amending the Banking and Financing Activities Act outlines obligations for credit institutions to disclose individual information for criminal investigations. Investigative authorities can impose disclosure restrictions to prevent compromising investigations, with time limits and international cooperation considerations.', 'Sweden', 'governance', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_19', ARRAY['sdg17', 'sweden', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
