INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('79c1116c-3219-57c5-ab1a-d7b001bc260b', 'Sweden Act amending the Securities Markets Act SFS 2024', 'Act amending the Securities Markets Act SFS 2024: 357', 'The Act amending the Securities Markets Act SFS 2024: 357 mandates that issuers must publish their annual and consolidated financial statements within four months after the end of each financial year. These reports must be audited and include a declaration of compliance with applicable accounting standards and sustainability reporting requirements. The law applies to all issuers, including those not based in the EEA that engage external auditors from third countries. This policy aims to enhance transparency and accountability in financial reporting and sustainability practices.', 'The Act amending the Securities Markets Act SFS 2024: 357 mandates that issuers must publish their annual and consolidated financial statements within four months after the end of each financial year. These reports must be audited and include a declaration of compliance with applicable accounting standards and sustainability reporting requirements. The law applies to all issuers, including those not based in the EEA that engage external auditors from third countries. This policy aims to enhance transparency and accountability in financial reporting and sustainability practices.', 'The Act amending the Securities Markets Act SFS 2024: 357 mandates that issuers must publish their annual and consolidated financial statements within four months after the end of each financial year. These reports must be audited and include a declaration of compliance with applicable accounting standards and sustainability reporting requirements. The law applies to all issuers, including those not based in the EEA that engage external auditors from third countries. This policy aims to enhance transparency and accountability in financial reporting and sustainability practices.', 'Sweden', 'climate', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_21', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ffd90fe5-5650-59fa-bf59-ef0a28bbb67c', 'Sweden Act amending the Insurance Business Act SFS 2024:358', 'Act amending the Insurance Business Act SFS 2024:358', 'The Act amending the Insurance Business Act SFS 2024:358 introduces new provisions for mutual insurance companies in Sweden, focusing on sustainability reporting and its auditing. It mandates that sustainability reports be included in financial reporting and requires independent audits of these reports. The act applies to mutual insurance companies, ensuring that they adhere to specific standards for sustainability reporting as outlined in EU directives. The requirements are mandatory, enhancing transparency and accountability in sustainability practices within the insurance sector.', 'The Act amending the Insurance Business Act SFS 2024:358 introduces new provisions for mutual insurance companies in Sweden, focusing on sustainability reporting and its auditing. It mandates that sustainability reports be included in financial reporting and requires independent audits of these reports. The act applies to mutual insurance companies, ensuring that they adhere to specific standards for sustainability reporting as outlined in EU directives. The requirements are mandatory, enhancing transparency and accountability in sustainability practices within the insurance sector.', 'The Act amending the Insurance Business Act SFS 2024:358 introduces new provisions for mutual insurance companies in Sweden, focusing on sustainability reporting and its auditing. It mandates that sustainability reports be included in financial reporting and requires independent audits of these reports. The act applies to mutual insurance companies, ensuring that they adhere to specific standards for sustainability reporting as outlined in EU directives. The requirements are mandatory, enhancing transparency and accountability in sustainability practices within the insurance sector.', 'Sweden', 'climate', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_22', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('41f5e014-efc9-5f27-bcfb-3a30f10ae573', 'Sweden Ordinence amending the Ordinence on Auditors SFS 2024:360', 'Ordinence amending the Ordinence on Auditors SFS 2024:360', 'The Ordinance amending the Ordinance on Auditors (SFS 2024:360) establishes new requirements for auditors in Sweden, specifically regarding their qualifications to audit sustainability reports. It mandates that authorized auditors must undergo at least eight months of practical training focused on sustainability report auditing. This policy applies to all auditors seeking authorization in Sweden and is part of a broader effort to enhance the quality of sustainability reporting. The policy is mandatory and will come into effect on July 1, 2024.', 'The Ordinance amending the Ordinance on Auditors (SFS 2024:360) establishes new requirements for auditors in Sweden, specifically regarding their qualifications to audit sustainability reports. It mandates that authorized auditors must undergo at least eight months of practical training focused on sustainability report auditing. This policy applies to all auditors seeking authorization in Sweden and is part of a broader effort to enhance the quality of sustainability reporting. The policy is mandatory and will come into effect on July 1, 2024.', 'The Ordinance amending the Ordinance on Auditors (SFS 2024:360) establishes new requirements for auditors in Sweden, specifically regarding their qualifications to audit sustainability reports. It mandates that authorized auditors must undergo at least eight months of practical training focused on sustainability report auditing. This policy applies to all auditors seeking authorization in Sweden and is part of a broader effort to enhance the quality of sustainability reporting. The policy is mandatory and will come into effect on July 1, 2024.', 'Sweden', 'climate', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_23', ARRAY['sdg4', 'regulations', 'mandatory', 'disclosure', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
