INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3e05b67a-04d5-596f-9d84-4e80845afbc4', 'Sweden Act amending the Savings Banks Act SFS 2024', 'Act amending the Savings Banks Act SFS 2024: 351', 'The Act amending the Savings Banks Act (SFS 2024:351) in Sweden updates regulations concerning the financial and sustainability reporting of savings banks. It mandates that the audit committee oversee both financial and sustainability reporting, ensuring reliability and compliance with internal controls and risk management. This policy applies to all savings banks in Sweden and introduces new requirements for the appointment of auditors, emphasizing the need for independence and expertise in sustainability reporting. The changes are mandatory and aim to enhance transparency and accountability in the banking sector.', 'The Act amending the Savings Banks Act (SFS 2024:351) in Sweden updates regulations concerning the financial and sustainability reporting of savings banks. It mandates that the audit committee oversee both financial and sustainability reporting, ensuring reliability and compliance with internal controls and risk management. This policy applies to all savings banks in Sweden and introduces new requirements for the appointment of auditors, emphasizing the need for independence and expertise in sustainability reporting. The changes are mandatory and aim to enhance transparency and accountability in the banking sector.', 'The Act amending the Savings Banks Act (SFS 2024:351) in Sweden updates regulations concerning the financial and sustainability reporting of savings banks. It mandates that the audit committee oversee both financial and sustainability reporting, ensuring reliability and compliance with internal controls and risk management. This policy applies to all savings banks in Sweden and introduces new requirements for the appointment of auditors, emphasizing the need for independence and expertise in sustainability reporting. The changes are mandatory and aim to enhance transparency and accountability in the banking sector.', 'Sweden', 'climate', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_25', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('504c3272-49bb-59d3-9f62-b23aa73ec246', 'Sweden Act amending the Act on Foreign Branches SFS', 'Act amending the Act on Foreign Branches SFS 2024: 352', 'The Act amending the Act on Foreign Branches introduces a new requirement for foreign branches in Sweden to prepare a sustainability report if mandated by existing annual reporting laws. This amendment specifies the auditing procedures that must be followed for these sustainability reports, aligning with EU directives on corporate sustainability reporting. The law is applicable to foreign branches operating in Sweden and is set to take effect on July 1, 2024. Compliance with the sustainability reporting requirements is mandatory for the affected entities.', 'The Act amending the Act on Foreign Branches introduces a new requirement for foreign branches in Sweden to prepare a sustainability report if mandated by existing annual reporting laws. This amendment specifies the auditing procedures that must be followed for these sustainability reports, aligning with EU directives on corporate sustainability reporting. The law is applicable to foreign branches operating in Sweden and is set to take effect on July 1, 2024. Compliance with the sustainability reporting requirements is mandatory for the affected entities.', 'The Act amending the Act on Foreign Branches introduces a new requirement for foreign branches in Sweden to prepare a sustainability report if mandated by existing annual reporting laws. This amendment specifies the auditing procedures that must be followed for these sustainability reports, aligning with EU directives on corporate sustainability reporting. The law is applicable to foreign branches operating in Sweden and is set to take effect on July 1, 2024. Compliance with the sustainability reporting requirements is mandatory for the affected entities.', 'Sweden', 'climate', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_26', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('25cc20c3-2419-5e80-93b1-667367940b1f', 'Sweden Act amending the Audit Act SFS 2024: 354', 'Act amending the Audit Act SFS 2024: 354', 'The Act amending the Audit Act SFS 2024:354 introduces mandatory requirements for the auditing of sustainability reports in Sweden. It specifies that audits must comply with standards set by EU directives, ensuring that sustainability reports are accurately assessed. The act applies to companies required to prepare sustainability reports, including parent companies and their subsidiaries. Auditors must provide a report on the sustainability report''s compliance with applicable laws and standards. This policy aims to enhance transparency and accountability in corporate sustainability practices.', 'The Act amending the Audit Act SFS 2024:354 introduces mandatory requirements for the auditing of sustainability reports in Sweden. It specifies that audits must comply with standards set by EU directives, ensuring that sustainability reports are accurately assessed. The act applies to companies required to prepare sustainability reports, including parent companies and their subsidiaries. Auditors must provide a report on the sustainability report''s compliance with applicable laws and standards. This policy aims to enhance transparency and accountability in corporate sustainability practices.', 'The Act amending the Audit Act SFS 2024:354 introduces mandatory requirements for the auditing of sustainability reports in Sweden. It specifies that audits must comply with standards set by EU directives, ensuring that sustainability reports are accurately assessed. The act applies to companies required to prepare sustainability reports, including parent companies and their subsidiaries. Auditors must provide a report on the sustainability report''s compliance with applicable laws and standards. This policy aims to enhance transparency and accountability in corporate sustainability practices.', 'Sweden', 'climate', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_27', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9a1c4353-8691-54e3-b41f-6f6a80a5ed0c', 'Sweden Act amending the Act on annual accounts', 'Act amending the Act on annual accounts in insurance companies SFS 2024:349', 'The Act amending the Act on annual accounts in insurance companies (SFS 2024:349) updates requirements for annual reporting by insurance companies in Sweden. It specifies the content of annual reports, including disclosures on financial performance, governance, and sustainability. The policy applies to all insurance companies, particularly those whose shares are traded on regulated markets. The changes are mandatory and align with EU directives on corporate sustainability reporting, enhancing transparency and accountability in the insurance sector.', 'The Act amending the Act on annual accounts in insurance companies (SFS 2024:349) updates requirements for annual reporting by insurance companies in Sweden. It specifies the content of annual reports, including disclosures on financial performance, governance, and sustainability. The policy applies to all insurance companies, particularly those whose shares are traded on regulated markets. The changes are mandatory and align with EU directives on corporate sustainability reporting, enhancing transparency and accountability in the insurance sector.', 'The Act amending the Act on annual accounts in insurance companies (SFS 2024:349) updates requirements for annual reporting by insurance companies in Sweden. It specifies the content of annual reports, including disclosures on financial performance, governance, and sustainability. The policy applies to all insurance companies, particularly those whose shares are traded on regulated markets. The changes are mandatory and align with EU directives on corporate sustainability reporting, enhancing transparency and accountability in the insurance sector.', 'Sweden', 'climate', 'in_force', '2024-01-01'::date, 'Sweden', 'https://www.carrotsandsticks.org/policies/171_28', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'sweden']::text[]) ON CONFLICT (id) DO NOTHING;
